"""Scanner/runner findings, extending source-aware review."""
import hashlib,json,pathlib,runpy
H=pathlib.Path(__file__).resolve().parent;P='additional_operad_skills_remaining';runpy.run_path(str(H/(P+'_synthesis10.py')));fs=json.loads((H/(P+'_preparation.json')).read_text())['files'];p=H/(P+'.json');r=json.loads(p.read_text())
def e(i,a,b):return {'path':fs[i]['path'],'sha256':fs[i]['sha256'],'lines':[a,b]}
def f(n,t,b,ev,a,v,severity='medium'):return {'id':f'OPSKILL-F{n:03}','severity':severity,'title':t,'finding':b,'evidence':ev,'recommended_action':a,'validation':v}
rows=[
f(95,'Scanner mode combination silently disables both rule families','CLI permits --arch-only and --pitfalls-only simultaneously; project sets AST rules empty and skips architecture pass. Parseable bad source then receives no active-rule findings, and console says codebase satisfies active rules.',[e(410,43,52),e(418,112,137),e(416,20,24)],'Make flags mutually exclusive or define one explicit mode enum; record enabled rule IDs and refuse zero-rule scans.','CHECK-073 evaluates the exact guards.','high'),
f(96,'Scanner dependency and test classification miss ordinary production cases','ImportedSymbol drops relative depth and dependency rule resolves only module, ignoring imported name and relative flag; from..import infrastructure therefore has an empty resolution key. Any filename containing test, including latest.py, is classified as test and exempted from architecture/assert checks. source_roots configuration is unused in package mapping.',[e(405,8,14),e(414,28,39),e(421,41,59),e(426,116,121),e(418,60,85)],'Resolve imports relative to actual packages/source roots, preserve depth and imported submodules, and use precise test patterns/explicit inventory rather than substring exemptions.','CHECK-074/076 demonstrate both false-negative paths.','high'),
f(97,'Noqa recognition treats string contents as suppression directives','Both suppression helpers regex-match raw lines without tokenizing comments. A production assert with message containing # noqa suppresses itself despite no actual comment. Policy exceptions therefore arise accidentally from string data.',[e(414,82,109),e(412,56,80),e(420,44,48)],'Use tokenize comment tokens with declared line scope and record every suppression in the receipt; fail malformed codes rather than dropping them.','CHECK-075 uses an in-memory assert with a literal message.'),
f(98,'Test runner does not propagate all failed prerequisites','Collection, mechanical gate and focused tests always execute in sequence regardless of earlier failure. Malformed gate stdout at exit0 creates GATE_ERROR but still labels gatePASS; final exit ignores collection failure. Subprocesses have no timeout and receipt discards raw outputs and exact argv, limiting replay/custody.',[e(431,30,63),e(431,66,116),e(431,136,139)],'Stop or explicitly isolate dependent execution after failed prerequisites, make parse/schema/findings failures fail closed, include collection in aggregate status and bind exact argv/full outputs/source/config with bounded timeouts.','CHECK-078 reproduces status logic on synthetic values without subprocess execution.','high'),
f(99,'Quality gate can pass unavailable targets and ineffective raises restrictions','File discovery silently ignores missing paths and pytest node IDs, yielding zero-file success. A match=None AST node is accepted as a match restriction. Presence of dead/nested assertions or arbitrary raises-named calls also satisfies no-assertion checks, which is consistent only with the stated narrow syntactic ceiling.',[e(432,148,169),e(432,181,197),e(432,302,332)],'Refuse unresolved/zero required populations and either resolve pytest selectors to files or accept explicit paths only. Validate effective match values and keep behavioral adequacy separate.','CHECK-077 demonstrates None bypass; other limits follow full body review.'),
f(100,'Scanner documentation promises a larger active rule set and stricter exit than supplied','Default registry contains24 AST rule classes plus three architecture rules; ViewDoesNotImportOrmRule exists but is not registered. README says findings imply nonzero exit, but controller returns0 for warning-only results. Several50-item rubric checks are not implemented and clean scan is not comprehensive review.',[e(396,67,80),e(400,78,80),e(423,68,118),e(424,512,537),e(425,49,57)],'Publish the exact active predicate inventory and severity exit policy, register/test intended missing rules, and retain README no-proof ceiling.','CHECK-079 records actual24 names; source inspection establishes registration/exit behavior.')]
d={x['id']:x for x in r['findings']};d.update({x['id']:x for x in rows});r['findings']=list(d.values())
vp=H/(P+'_checks10.json');v={'path':'dag/reviews/'+vp.name,'sha256':hashlib.sha256(vp.read_bytes()).hexdigest(),'description':'Seven independent source-predicate controls; no scanner/test/provider execution.'};r['validation']=[x for x in r['validation']if x['path']!=v['path']]+[v];p.write_text(json.dumps(r,indent=2)+'\n')
(H/(P+'.md')).write_text('\n'.join(['# Operad skills audit — in progress','',f"**{r['full_source_read_count']}/{r['scope_count']} full bodies reviewed; {len(r['remaining_work'])} pending.** Exact pins/ranges and per-file assessments in JSON.",'',f"{len(r['claims'])} claims, {len(r['findings'])} findings;78 observed independent controls and one unavailable shell control.",'','Useful mechanisms include finite mathematical witnesses, explicit admitted carriers, real AST rule interfaces, missing-target errors, and scope-aware receipts.','','Material defects span false mathematical implications, evidence-label upgrades, stale statement dispositions, dropped extraction rows and scanner/test-runner failure paths. The latest controls show mutually disabling flags, relative-import and filename exemptions, literal-string suppressions and incomplete prerequisite failure propagation.','','No original bytes changed and no retained workflow, provider or native build executed. Remaining scope stays explicit.'])+'\n');print(json.dumps({'full':r['full_source_read_count'],'findings':len(r['findings'])}))
